904→  'used_textures_bytes', 'used_textures_count', 'total_reserved_memory',
905→  'total_used_memory', 'gc_allocated_in_frame', 'gc_reserved_memory',
906→  'system_used_memory', 'particle_memory', 'mesh_memory',
907→  'material_count', 'object_count',
908→] as const;
909→
910→export function queryFrameCounters(
911→  db: Database.Database,
912→  args: QueryFrameCountersArgs
913→): QueryFrameCountersResult {
914→  const { runId, frames } = args;
915→
916→  if (frames && frames.length > 0) {
917→    // Return specific frames (cap 50)
918→    const capped = frames.slice(0, 50);
919→    const placeholders = capped.map(() => '?').join(',');
920→    const sql = `
921→      SELECT frame_index, ${COUNTER_COLS.join(', ')}
922→      FROM prism_frame_counters
923→      WHERE run_id = ? AND frame_index IN (${placeholders})
924→      ORDER BY frame_index
925→    `;
